INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES ("", 6010, 0, "", "vo_minigame_1013_top_talk_6_001", "", 6, "vo_minigame_1013", "", 21, 0);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (0, 6011, 6, 0, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 0.8, 6, 129911, 0, 11, 1);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES ("", 6012, "", "", "", "", 6, 0, "", 91, "");
