INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (1, 6014, 0, "", "drama_talk_surprise_in_shy", "", 6, 129811, 0.2, 3, "drama_talk_surprise_loop_shy");
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES ("", 6015, 0, "", "vo_minigame_1013_top_talk_6_002", "", 6, "vo_minigame_1013", "", 21, 0);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (0, 6016, 9, 0, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 0.3, 6, 129811, 0, 11, 1);
INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES ("", 6017, "", "", "", "", 6, 0, "", 91, "");
