INSERT INTO `v1_0d733b39c1b4f200ecde636d692b961d65fd6243bd3e5ac7dc3edea76b5ec890` VALUES (0, 8016, 7, 0, "くっ、そう言われると\n悔しいな…！\nならこの行軍訓練で\n逆転してやるぜ！", 0.3, 8, 129811, 0, 11, 1);
